def _round_half_up(value, digits=2):
    """PATCH_629: round half away from zero (四捨五入), to the given number of
    decimal digits. Python's built-in round() uses round-half-to-even and is
    also subject to binary floating-point representation error (e.g.
    round(2.005, 2) can yield 2.0 instead of 2.01); Decimal-based rounding
    avoids both issues for user-entered quantities."""
    from decimal import Decimal, ROUND_HALF_UP
    try:
        quant = Decimal("1").scaleb(-digits)
        return float(Decimal(str(value)).quantize(quant, rounding=ROUND_HALF_UP))
    except Exception:
        return round(float(value), digits)

def _to_canonical_english(value):
    if value is None or not isinstance(value, str):
        return value
    s = value
    for ja, en in _CANONICAL_REPLACEMENTS:
        s = s.replace(ja, en)
    s = s.replace("・", " / ").replace("：", ": ").replace("（", " (").replace("）", ")")
    return re.sub(r"\s+", " ", s).strip()

def _canonicalize_takeoff_row(row):
    """Attach/persist canonical English fields without destroying original evidence."""
    if not isinstance(row, dict):
        return row
    original = row.setdefault("source_text_original", {})
    if not isinstance(original, dict):
        original = {}
        row["source_text_original"] = original

    mapping = (
        ("item", "canonical_item"),
        ("evidence", "canonical_evidence"),
        ("source_mode", "canonical_source_mode"),
        ("category", "canonical_category"),
        ("specification", "canonical_specification"),
        ("calculation_basis", "canonical_calculation_basis"),
        ("formula", "canonical_formula"),
    )
    for src, dst in mapping:
        value = row.get(src)
        if isinstance(value, str) and value:
            original.setdefault(src, value)
            row[dst] = _to_canonical_english(value)

    row["canonical_language"] = "en"
    row["canonical_schema_version"] = "1.0"
    return row


