# PATCH_255 — canonical system vocabulary (not drawing text).
# These are stable AZRAS-generated codes/labels used by status, quality and
# performance records. Drawing-native strings remain outside this registry.
_CANONICAL_SYSTEM_CODES = {
    "confirmed": {"label":"Confirmed", "severity":"ok"},
    "estimated": {"label":"Estimated", "severity":"warning"},
    "unresolved": {"label":"Unresolved", "severity":"warning"},
    "manual": {"label":"Manual", "severity":"info"},
    "not_applicable": {"label":"Not applicable", "severity":"info"},
    "drawing_confirmed": {"label":"Drawing confirmed", "severity":"ok"},
    "specification_confirmed": {"label":"Specification confirmed", "severity":"ok"},
    "quantity_unresolved": {"label":"Quantity unresolved", "severity":"warning"},
    "additional_documents_required": {"label":"Additional documents required", "severity":"warning"},
}

def _canonical_system_status(value):
    raw=str(value or "").strip()
    low=raw.lower()
    aliases={
        "確認済":"confirmed",
        "確定":"confirmed",
        "推定":"estimated",
        "未確定":"unresolved",
        "review required":"unresolved",
        "手動":"manual",
        "対象外":"not_applicable",
        "図面確認済":"drawing_confirmed",
        "仕様確認済":"specification_confirmed",
        "数量未確定":"quantity_unresolved",
        "追加資料必要":"additional_documents_required",
    }
    code=aliases.get(raw, aliases.get(low, low))
    if code not in _CANONICAL_SYSTEM_CODES:
        code=code or "unresolved"
    meta=_CANONICAL_SYSTEM_CODES.get(code, {"label":code.replace("_"," ").title(),"severity":"info"})
    return code,meta["label"],meta["severity"]


