def _canonical_en_generated_text(value):
    """Normalize generated analysis/status prose to English canonical form.
    Source drawing text must be retained separately as source_text_original.
    """
    if value is None or not isinstance(value, str):
        return value
    out = value
    for ja, en in sorted(_CANONICAL_EN_REPLACEMENTS.items(), key=lambda kv: len(kv[0]), reverse=True):
        out = out.replace(ja, en)
    return out

