        self.assumptions=json.loads((self.root_dir/"data"/"quantity_assumptions_v6.json").read_text(encoding="utf-8"))
        self.rebar=json.loads((self.root_dir/"data"/"azras_rebar_takeoff_v6_1.json").read_text(encoding="utf-8"))
