    def _enforce_project_retention_policy(self, building_system_changed=False):
        """PATCH_598: keep only current saved user state and current AI imports.

        Retention policy:
        1) Current values explicitly saved in Project JSON by the user/designer remain.
        2) Current AI-import snapshots remain, one per canonical provider.
        3) Historical human-review ledgers/source references are deleted, not retained.
        4) When the building system changes, all AI-imported state is invalid for the
           new system and is deleted from the active Project state.
        """
        if not isinstance(self.project,dict):
            return {"human_history_removed":0,"ai_state_removed":0}
        removed_human=0
        removed_ai=0
        common=self.project.setdefault("common",{})

        # Human-review persistence is CURRENT STATE ONLY.
        # Keep current parameters and manual quantity overrides, but never an
        # accumulating decision ledger or old source-file history.
        hr=common.get("module1_human_review_parameters")
        if isinstance(hr,dict):
            for k in ("decision_ledger","source_review_excel","source_final_json",
                      "previous_decisions","history","audit_history"):
                if k in hr:
                    hr.pop(k,None); removed_human+=1
            params=hr.get("parameters")
            if not isinstance(params,dict) or not params:
                common.pop("module1_human_review_parameters",None)
            else:
                common["module1_human_review_parameters"]={
                    "schema":"AZRAS_MODULE1_HUMAN_REVIEW_PARAMETERS_V1",
                    "priority":"explicit user/designer instruction > AI final review > drawing-derived estimate",
                    "parameters":params,
                }

        # Strip historical human-answer provenance from rows. The active adopted
        # quantity itself is retained because it is current Project-JSON state.
        outputs=self.project.get("module_outputs") if isinstance(self.project.get("module_outputs"),dict) else {}
        m1=outputs.get("module1") if isinstance(outputs.get("module1"),dict) else {}
        qto=m1.get("quantity_takeoff") if isinstance(m1.get("quantity_takeoff"),dict) else {}
        qto.pop("ai_"+"review_history",None)
        rows=qto.get("rows") if isinstance(qto.get("rows"),list) else []
        row_history_keys=(
            "human_review_final_source_json","manual_override_original_value",
            "manual_override_original_unit","manual_override_original_status",
            "manual_override_original_source_mode","previous_human_answer",
            "human_review_history","decision_history",
        )
        for row in rows:
            if not isinstance(row,dict): continue
            for k in row_history_keys:
                if k in row:
                    row.pop(k,None); removed_human+=1

        if building_system_changed:
            # Current AI evidence belongs to the old building system and must not
            # be consulted after the system switch.
            common_ai_keys=(
                "ai_takeoff_provider_reviews","ai_takeoff_provider_reviewers",
                "ai_takeoff_provider_review_count","ai_takeoff_collection",
                "ai_takeoff_recheck_request","ai_takeoff_final_review",
                "ai_takeoff_collection_status","north_rotation_resolution",
            )
            for k in common_ai_keys:
                if k in common:
                    common.pop(k,None); removed_ai+=1

            # Remove mirrored AI state from every current Module 1 representation.
            for holder in (m1,):
                if not isinstance(holder,dict): continue
                for k in ("ai_takeoff_collection","ai_takeoff_recheck_request",
                          "ai_takeoff_final_review","ai_takeoff_import",
                          "ai_takeoff_import_payload","ai_takeoff_file"):
                    if k in holder:
                        holder.pop(k,None); removed_ai+=1
                for qkey in ("quantity_takeoff","quantity_takeoff_canonical"):
                    qq=holder.get(qkey)
                    if not isinstance(qq,dict): continue
                    for k in ("ai_provider_reviews","ai_provider_reviewers",
                              "ai_provider_review_count","ai_first_round_policy",
                              "ai_reapplied_after_full_rebuild",
                              "ai_reapplied_provider_count","ai_final_review_applied",
                              "ai_final_review_source_json"):
                        if k in qq:
                            qq.pop(k,None); removed_ai+=1
                    for row in qq.get("rows") or []:
                        if not isinstance(row,dict): continue
                        for k in (
                            "ai_reviews","ai_final_review","ai_final_conflict_reported",
                            "ai_final_unresolved","ai_human_review_required",
                            "ai_human_confirmed","ai_first_round_reviewers",
                            "ai_first_round_policy_note_ja","ai_first_round_policy_note_en",
                            "carried_forward_omitted_scope"
                        ):
                            if k in row:
                                row.pop(k,None); removed_ai+=1

            self.ai_takeoff_import=None
            self.ai_takeoff_pending_payload=None
            self.ai_takeoff_pending_path=None
            try:self.ai_takeoff_file.set("")
            except Exception:pass

            # The active R1 AI evidence belongs to the selected Building System.
            # On a system switch, remove R1 so evidence from the previous system
            # cannot be consumed by the newly selected system.
            try:
                round_root=self._ai_round_root()
                if round_root.exists():
                    shutil.rmtree(round_root,ignore_errors=True)
            except Exception:
                pass

        return {"human_history_removed":removed_human,"ai_state_removed":removed_ai}

    def _persist_retention_cleanup(self):
        """Apply retention policy and immediately persist the cleaned Project JSON."""
        info=self._enforce_project_retention_policy(building_system_changed=False)
        if isinstance(self.project,dict) and self.project_path is not None:
            save_project(self.project,self.project_path)
            if self.project_context is not None:
                self.project_context.set(self.project_path,self.project)
        return info

    # PATCH_210: resolve persisted orientation by evidence, not by one storage key.
    # A later AI run may legitimately return null/unresolved; that means "no new
    # evidence" and must not erase a previously confirmed value from the same
    # Project JSON.  This helper searches all Module 1 persistence locations that
    # have existed across prior patches and returns the best evidence-backed value.
    def _persisted_orientation_candidates(self):
        project=self.project if isinstance(self.project,dict) else {}
        common=project.get("common") if isinstance(project.get("common"),dict) else {}
        building=common.get("building") if isinstance(common.get("building"),dict) else {}
        outputs=project.get("module_outputs") if isinstance(project.get("module_outputs"),dict) else {}
        m1=outputs.get("module1") if isinstance(outputs.get("module1"),dict) else {}
        profile=m1.get("profile") if isinstance(m1.get("profile"),dict) else {}
        geom=profile.get("geometry") if isinstance(profile.get("geometry"),dict) else {}
        ai_payload=m1.get("ai_takeoff_import_payload") if isinstance(m1.get("ai_takeoff_import_payload"),dict) else {}
        ai_bp=ai_payload.get("building_profile") if isinstance(ai_payload.get("building_profile"),dict) else {}
        ai_geom=ai_bp.get("geometry") if isinstance(ai_bp.get("geometry"),dict) else {}
        comp=project.get("comparison_export") if isinstance(project.get("comparison_export"),dict) else {}
        comp_building=comp.get("common_building") if isinstance(comp.get("common_building"),dict) else {}

        return [
            (common.get("north_rotation_deg"), common.get("orientation_evidence"), "common.north_rotation_deg"),
            (building.get("north_rotation_deg"), building.get("orientation_evidence"), "common.building.north_rotation_deg"),
            (geom.get("north_rotation_deg"), geom.get("orientation_evidence"), "module_outputs.module1.profile.geometry.north_rotation_deg"),
            (profile.get("north_rotation_deg"), geom.get("orientation_evidence") or profile.get("orientation_evidence"), "module_outputs.module1.profile.north_rotation_deg"),
            (ai_geom.get("north_rotation_deg"), ai_geom.get("orientation_evidence"), "module_outputs.module1.ai_takeoff_import_payload.building_profile.geometry.north_rotation_deg"),
            (comp_building.get("north_rotation_deg"), comp_building.get("orientation_evidence"), "comparison_export.common_building.north_rotation_deg"),
        ]

    @staticmethod
    def _coalesce_present(*values, default=None):
        """PATCH_520: first non-null/non-blank value; numeric 0/0.0 is valid."""
        for value in values:
            if value is None:
                continue
            if isinstance(value, str) and value.strip()=="":
                continue
            return value
        return default

    @staticmethod
    def _format_north_rotation_ui(value):
        """PATCH_519: display valid north rotation values with one decimal place.

        In particular, 0.0 is a real resolved angle and must never be collapsed
        into an empty string or treated as False.
        """
        try:
            v=float(value) % 360.0
        except (TypeError,ValueError):
            return ""
        if not math.isfinite(v):
            return ""
        if abs(v-360.0) < 1e-9 or abs(v) < 1e-9:
            v=0.0
        return f"{v:.1f}"

    @staticmethod
    def _normalized_orientation_candidate(value,evidence,source):
        if value in (None, ""):
            return None
        try:
            v=float(value)
        except (TypeError,ValueError):
            return None
        if not math.isfinite(v):
            return None
        # Normalize rotations to [0,360); 0 remains a valid, meaningful value.
        v=v % 360.0
        ev=evidence if isinstance(evidence,dict) else {}
        status=str(ev.get("evidence_status") or ev.get("status") or "").strip().lower()
        confidence=0.0
        try: confidence=float(ev.get("confidence") or 0.0)
        except Exception: confidence=0.0
        return {"value":v,"evidence":dict(ev),"status":status,"confidence":confidence,"source":source}

    def _resolve_orientation(self,new_geometry=None):
        """PATCH_210 evidence priority: new confirmed > persisted confirmed >
        new estimated > persisted estimated > unresolved.  Null is never 0°."""
        candidates=[]
        if isinstance(new_geometry,dict):
            c=self._normalized_orientation_candidate(
                new_geometry.get("north_rotation_deg"),
                new_geometry.get("orientation_evidence"),
                "new_ai.building_profile.geometry.north_rotation_deg",
            )
            if c: candidates.append(c)
        for value,evidence,source in self._persisted_orientation_candidates():
            c=self._normalized_orientation_candidate(value,evidence,source)
            if c: candidates.append(c)
        if not candidates:
            return None
        rank={"confirmed":4,"estimated":2}
        # confirmed always outranks estimated; for equal class prefer the new AI,
        # then higher confidence, then earlier persistent source order.
        def score(c):
            source_bonus=1 if c["source"].startswith("new_ai.") else 0
            return (rank.get(c["status"],0),source_bonus,c["confidence"])
        best=max(candidates,key=score)
        if rank.get(best["status"],0)<=0:
            return None
        return best

    def _update_north_staleness_warning(self,*_args):
        """PATCH_378: warn when the north-rotation field has been edited since
        the last completed "解析を実行" run.

        Typing a new value into the north field (or saving the project) does
        not by itself re-run the PDF analysis: orientation-dependent results
        (drawing_analysis.north_rotation_confirmed, profile.north_rotation_deg,
        wall/window/door area by orientation, girt orientation per face, etc.)
        are only recomputed the next time run() executes analyze_pdf(). Without
        this warning, a user can type a rotation, save, and reasonably believe
        it was applied when it was not.
        """
        if not hasattr(self,"north_stale_label"):
            return
        if not getattr(self,"_north_last_analyzed_known",False):
            try: self.north_stale_label.config(text="")
            except Exception: pass
            try: self.north_entry.config(bg=INPUT_BG)
            except Exception: pass
            return
        try:
            current=self._nullable_float(self.north.get())
        except Exception:
            current=None
        baseline=self._north_last_analyzed_value
        stale=(current!=baseline)
        try:
            if stale:
                self.north_stale_label.config(text=(
                    "⚠ 方位（北方位入力欄）が最後に「解析を実行」した時の値と異なります。"
                    "図面解析・数量計算へ反映するには、もう一度「解析を実行」してください。"
                    if self.i18n.language=="ja" else
                    "⚠ The north-rotation value differs from the last completed analysis run. "
                    "Click \"Analyze\" again to apply it to the drawing analysis and quantities."
                ))
                self.north_entry.config(bg="#ffd8a8")
            else:
                self.north_stale_label.config(text="")
                self.north_entry.config(bg=INPUT_BG)
        except Exception:
            pass

    def _apply_resolved_orientation(self,new_geometry=None,target_geometry=None,target_profile=None):
        resolved=self._resolve_orientation(new_geometry)
        if resolved is None:
            self.north.set("")
            if isinstance(target_geometry,dict): target_geometry["north_rotation_deg"]=None
            if isinstance(target_profile,dict): target_profile["north_rotation_deg"]=None
            return None
        north=float(resolved["value"])
        evidence=dict(resolved.get("evidence") or {})
        self.north.set(self._format_north_rotation_ui(north))
        if isinstance(target_geometry,dict):
            target_geometry["north_rotation_deg"]=north
            if evidence: target_geometry["orientation_evidence"]=evidence
        if isinstance(target_profile,dict): target_profile["north_rotation_deg"]=north
        if self.project is not None:
            common=self.project.setdefault("common",{})
            common["north_rotation_deg"]=north
            if evidence: common["orientation_evidence"]=evidence
            building=common.get("building") if isinstance(common.get("building"),dict) else None
            if building is not None:
                building["north_rotation_deg"]=north
                if evidence: building["orientation_evidence"]=evidence
        return resolved

    def _recover_project_context_from_open_windows(self):
        """Recover the active Project JSON from another open module window.

        PATCH_239: Language/cover rebuilds must not make Module 1 lose the
        project already selected in Module 0 (or another module).  This is a
        process-local fallback only; it does not guess a project from disk.
        """
        if self.project_context is None:
            return False
        if self.project_context.path is not None:
            return True

        root = self.winfo_toplevel()
        # Module 1 itself is a Toplevel, so walk up to the launcher/root first.
        try:
            while getattr(root, "master", None) is not None:
                parent = root.master
                if parent is None:
                    break
                root = parent
        except tk.TclError:
            return False

        def walk(widget):
            try:
                children = list(widget.winfo_children())
            except tk.TclError:
                return
            for child in children:
                yield child
                yield from walk(child)

        for win in walk(root):
            if win is self:
                continue
            candidate = getattr(win, "path", None) or getattr(win, "project_path", None)
            if not candidate:
                continue
            try:
                candidate_path = Path(candidate)
                if not candidate_path.exists() or candidate_path.suffix.lower() != ".json":
                    continue
                candidate_project = getattr(win, "project", None)
                self.project_context.set(
                    candidate_path,
                    candidate_project if isinstance(candidate_project, dict) else None,
                )
                return True
            except Exception:
                continue
        return False

    def _refresh_project_state_notice(self):
        if not hasattr(self, "project_state_notice"):
            return
        project = self.project if isinstance(self.project, dict) else {}
        output = (project.get("module_outputs") or {}).get("module1")
        if isinstance(output, dict) and output and not module_output_is_current(project, "module1"):
            status = str(((project.get("module_status") or {}).get("module1") or {}).get("status") or "stale")
            if self.i18n.language == "ja":
                self.project_state_notice.set(f"⚠ Module 1は再計算が必要です（{status}）。再計算してProject JSONへ保存してください。")
            else:
                self.project_state_notice.set(f"⚠ Module 1 requires recalculation ({status}). Recalculate and save it to the Project JSON.")
        else:
            self.project_state_notice.set("")

    def refresh_project_from_context(self, event=None):
        """Use the launcher-wide Project JSON selected or created in Module 0."""
        if self.project_context is None:
            return False

        # PATCH_239: if a language/cover rebuild temporarily left the shared
        # context path empty, recover it from an already-open module window.
        if self.project_context.path is None:
            self._recover_project_context_from_open_windows()

        if self.project_context.path is None:
            return False

        active_path = self.project_context.path
        current_path = getattr(self, "project_path", None)
        if current_path is None or Path(current_path) != Path(active_path):
            self.project = self.project_context.reload()
            self.project_path = active_path
            if hasattr(self, "project_file"):
                self.project_file.set(self.project_context.display_path)
        elif self.project is None:
            self.project = self.project_context.reload()
        self._refresh_project_state_notice()
        return True

