        tree.column("items",width=60,anchor="e"); tree.column("imported",width=165,anchor="w")
        tree.pack(fill="both",expand=True)
        detail=tk.Text(right,wrap="none",font=("Consolas",9)); detail.pack(fill="both",expand=True)
